import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { CheckCircle, XCircle } from "lucide-react";

import {
  signInWithEmailAndPassword,
  signInWithPopup,
} from "firebase/auth";

import { auth, googleProvider } from "../firebase";

const Login = () => {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");

  const [loading, setLoading] = useState(false);
  const [googleLoading, setGoogleLoading] = useState(false);

  const [popup, setPopup] = useState({
    show: false,
    message: "",
    type: "success",
  });

  const navigate = useNavigate();

  const showPopup = (message, type = "success") => {
    setPopup({ show: true, message, type });

    setTimeout(() => {
      setPopup({ show: false, message: "", type: "success" });
    }, 2000);
  };

  // 🔐 EMAIL LOGIN
  const handleLogin = async (e) => {
    e.preventDefault();
    setLoading(true);

    try {
      const res = await signInWithEmailAndPassword(auth, email, password);

      const user = res.user;

      localStorage.setItem("userId", user.uid);
      localStorage.setItem("email", user.email);

      showPopup("Login successful!", "success");

      setTimeout(() => navigate("/dashboard"), 800);
    } catch (err) {
      showPopup(err.message, "error");
    } finally {
      setLoading(false);
    }
  };

  // 🔵 GOOGLE LOGIN
  const handleGoogleLogin = async () => {
    setGoogleLoading(true);

    try {
      const result = await signInWithPopup(auth, googleProvider);

      const user = result.user;

      localStorage.setItem("userId", user.uid);
      localStorage.setItem("email", user.email);
      localStorage.setItem("name", user.displayName || "");

      showPopup("Google login successful!", "success");

      setTimeout(() => navigate("/dashboard"), 800);
    } catch (error) {
      showPopup("Google login failed", "error");
    } finally {
      setGoogleLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-50 px-4">

      {/* POPUP */}
      {popup.show && (
        <div
          className={`fixed top-6 left-1/2 -translate-x-1/2 flex items-center gap-2 px-4 py-2 rounded-md shadow border text-sm ${
            popup.type === "success"
              ? "text-green-700 border-green-200 bg-white"
              : "text-red-700 border-red-200 bg-white"
          }`}
        >
          {popup.type === "success" ? (
            <CheckCircle className="w-4 h-4" />
          ) : (
            <XCircle className="w-4 h-4" />
          )}
          {popup.message}
        </div>
      )}

      {/* FORM */}
      <div className="w-full max-w-sm">

        <h1 className="text-xl font-semibold mb-1">Spendly</h1>
        <p className="text-sm text-gray-500 mb-6">
          Track your spending with clarity
        </p>

        <form onSubmit={handleLogin} className="space-y-3">
          <input
            type="email"
            placeholder="Email"
            value={email}
            required
            onChange={(e) => setEmail(e.target.value)}
            className="w-full px-3 py-2 border rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
          />

          <input
            type="password"
            placeholder="Password"
            value={password}
            required
            onChange={(e) => setPassword(e.target.value)}
            className="w-full px-3 py-2 border rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
          />

          <button
            type="submit"
            disabled={loading}
            className="w-full bg-black text-white py-2 rounded-md hover:bg-gray-900"
          >
            {loading ? "Signing in..." : "Sign in"}
          </button>
        </form>

        {/* GOOGLE LOGIN */}
        <button
          type="button"
          onClick={handleGoogleLogin}
          disabled={googleLoading}
          className="w-full mt-3 border py-2 rounded-md hover:bg-gray-100"
        >
          {googleLoading
            ? "Signing in..."
            : "Continue with Google"}
        </button>

        <p className="text-sm text-gray-500 mt-6">
          No account?{" "}
          <span
            onClick={() => navigate("/register")}
            className="text-black font-medium cursor-pointer hover:underline"
          >
            Create one
          </span>
        </p>
      </div>
    </div>
  );
};

export default Login;
